import React, { useState } from "react";
import "./Explore.css";

/* 필요한 경우 프로젝트 자산 경로로 바꿔줘 */
import noticeIcon from "../assets/공지사항.png";

const SIDE_ITEMS = ["대산읍", "지곡면", "팔봉면", "성연면", "음암면", "운산면", "부춘동", "동문1동"];

const MOCK_LIST = [
  {
    id: 1,
    title: "아동 청소년을 위한 청소년 수련관 운영",
    body: "청소년활동진흥법의 규정에 따라 청소년활동을 적극적으로 진흥하기 위해 다양한 수련거리를 실시할 수 있도록 청소년 수련관을 운영하고자 ○○에 위치한 …"
  },
  { id: 2, title: "제목", body: "2줄" },
  {
    id: 3,
    title: "아동 청소년을 위한 청소년 수련관 운영",
    body: "청소년활동진흥법의 규정에 따라 청소년활동을 적극적으로 진흥하기 위해 다양한 수련거리를 실시할 수 있도록 청소년 수련관을 운영하고자 ○○에 위치한 …"
  }
];

export default function Explore() {
  const [activeSide, setActiveSide] = useState(0);
  const [openMenu, setOpenMenu] = useState(null); // "news" | "welfare" | ...

  const toggleMenu = (key) => setOpenMenu((k) => (k === key ? null : key));

  return (
    <main className="page">
      <div className="frame">
        {/* ===== 왼쪽 사이드 (sticky) ===== */}
        <aside className="side">
          <div className="sideTitle">지역</div>
          <ul className="sideList">
            {SIDE_ITEMS.map((label, i) => (
              <li
                key={label}
                className={`sideItem ${i === activeSide ? "sideItemActive" : ""}`}
                onClick={() => setActiveSide(i)}
              >
                {label}
              </li>
            ))}
          </ul>
        </aside>

        {/* ===== 메인 ===== */}
        <section className="main">
          {/* 상단 탭 */}
          <div className="tabPill">
            {[
              { key: "news", label: "뉴스" },
              { key: "welfare", label: "복지" },
              { key: "culture", label: "문화소식" },
              { key: "city", label: "서산시청" },
              { key: "cafe", label: "카페" },
              { key: "blog", label: "블로그" }
            ].map((t) => (
              <div className="tabItem" key={t.key}>
                <button
                  className={`tabBtn ${openMenu === t.key ? "tabBtnActive" : ""}`}
                  onClick={() => toggleMenu(t.key)}
                >
                  {t.label}
                  <span className={`caret ${openMenu === t.key ? "caretUp" : ""}`}>▲</span>
                </button>

                {/* 드롭다운 메뉴 */}
                {openMenu === t.key && (
                  <div className="ddMenu">
                    <ul className="ddList">
                      <li className="ddItem">최신순</li>
                      <li className="ddItem">인기순</li>
                      <li className="ddItem">기간 설정</li>
                    </ul>
                  </div>
                )}
              </div>
            ))}
          </div>

          {/* 결과 카운트 */}
          <div className="countBar">
            <span className="countIconWrap">
              <img className="noticeIcon" src={noticeIcon} alt="검색" />
            </span>
            글 전체 결과 3,435개
          </div>

          {/* 리스트 */}
          <div className="list">
            {MOCK_LIST.map((item) => (
              <article className="card" key={item.id}>
                <h3 className="cardTitle">{item.title}</h3>
                <div className="divider" />
                <p className="cardBody">{item.body}</p>
                <div className="cardFooter">
                  <a href="#" className="viewLink">보기</a>
                  <button className="circleIcon" aria-label="바로가기">
                    <img className="noticeIcon" src={noticeIcon} alt="" />
                  </button>
                </div>
              </article>
            ))}
          </div>
        </section>
      </div>
    </main>
  );
}
